UPDATE products SET price = 395000, wholesale_price = 350000, reseller_price = 370000, description = 'The PlayStation Portal Remote Player liberates your PS5 gaming from the living room. This stunning 8-inch LCD screen with 1080p resolution and 60fps capability streams your PS5 games via WiFi, allowing you to play your entire library from anywhere in your home. The integrated DualSense controls feature the same haptic feedback and adaptive triggers as your console controller. With a lightweight, ergonomic design and seamless Remote Play integration, your PS5 games follow you to bed, the kitchen, or the backyard. Requires PS5 console and WiFi connection. Brand new, sealed in original Sony packaging with 1-year Sony warranty.' WHERE id = 'playstation-portal-2';

UPDATE products SET price = 135000, wholesale_price = 115000, reseller_price = 125000, description = 'The Sony Pulse 3D Wireless Headset is engineered specifically for the PlayStation 5 3D AudioTech. Featuring dual hidden noise-canceling microphones, fine-tuned audio drivers, and USB Type-C wireless adapter compatibility, this headset delivers the spatial soundscapes that PS5 games are designed around. The refined over-ear design with plush ear cushions ensures comfort during extended sessions, while the easy-access controls for game/chat balance and mic monitoring put you in command. With up to 12 hours of wireless battery life, this is the definitive PS5 audio experience. Compatible with PS5, PS4, PC, and Mac. Brand new, sealed in original Sony packaging.' WHERE id = 'ps5-pulse-3d-headset';

UPDATE products SET price = 695000, wholesale_price = 620000, reseller_price = 655000 WHERE id = 'starlink-v4-standard';

UPDATE products SET price = 445000, wholesale_price = 390000, reseller_price = 415000 WHERE id = 'starlink-mini-v4';

UPDATE products SET price = 125000, wholesale_price = 105000, reseller_price = 115000 WHERE id = 'airtel-5g-router';

UPDATE products SET price = 345000, wholesale_price = 300000, reseller_price = 320000, description = 'The DualSense Edge is Sony professional-grade wireless controller engineered for esports competitors and serious gamers. Featuring ultra-customizable back buttons, replaceable stick modules, adjustable trigger dead zones, and swappable stick caps, this controller adapts to your unique playstyle. The customizable control profiles let you switch between game-specific configurations instantly. With the same revolutionary haptic feedback and adaptive triggers as the standard DualSense, plus a premium hard-shell carrying case, braided USB cable, and stick module replacement tools, this is the ultimate competitive advantage. Brand new, sealed, original Sony packaging.' WHERE id = 'dualsense-edge-controller';

UPDATE products SET price = 115000, wholesale_price = 95000, reseller_price = 105000 WHERE id = 'ps5-dualsense-controller';

