-- PS5 Slim Carry Bag (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ps5-slim-carry-bag', 'PS5 Slim Protective Carry Bag - Brand New - Lightweight, Foam Padded, Travel Friendly', 'gaming', 52000, 52000, 42000, 10, 0.90, '/assets/products/ps5-slim-carry-bag.webp', 'Designed specifically for the compact PS5 Slim form factor, this carry bag offers tailored protection with a precision-cut foam interior. The lightweight yet durable construction features water-resistant material, padded controller compartments, and game storage pockets. Whether you are a mobile gamer or simply need safe storage, this bag ensures your PS5 Slim arrives at its destination in pristine condition. The ergonomic handle and optional shoulder strap provide versatile carrying options. Compatible with PS5 Slim Digital and Disc Editions. Brand new, sealed, premium third-party accessory.', 1, 1718400000, 1, 42000, '/assets/products/ps5-slim-carry-bag.webp', 47000, 4.4, 0, 'Generic', 0, 1, 'gadgets');

-- PS4 DualShock 4 Controller (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ps4-dualshock-4-controller', 'Sony PS4 DualShock 4 Wireless Controller - Original - Precision Control, Touchpad, Light Bar', 'gaming', 95000, 95000, 78000, 10, 0.22, '/assets/products/ps4-dualshock-4-controller.webp', 'The iconic Sony DualShock 4 wireless controller defined a generation of PlayStation gaming. Featuring precision analog sticks, a responsive touchpad, built-in mono speaker, 3.5mm headset jack, and the revolutionary Share button, this controller remains essential for PS4 gaming and is fully compatible with PS5 for backward-compatible PS4 titles. The integrated light bar changes color based on in-game events, while the Sixaxis motion sensing adds intuitive control. The ergonomic design with textured grips provides comfort during marathon sessions. Available in Jet Black. Original Sony product — tested, clean exterior, all buttons and sensors operational. Fully functional with excellent cosmetic condition.', 1, 1718400000, 1, 78000, '/assets/products/ps4-dualshock-4-controller.webp', 86000, 4.6, 0, 'Sony', 0, 0, 'gadgets');

-- PS4 Generic X Controller (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ps4-generic-x-controller', 'PS4 Compatible Wireless Controller - X Design - Vibration Feedback, USB Charging', 'gaming', 22000, 22000, 17000, 15, 0.22, '/assets/products/ps4-generic-x-controller.webp', 'A budget-friendly alternative for PS4 gamers seeking a functional backup or secondary controller. This third-party gamepad features standard dual analog sticks, directional pad, action buttons, and shoulder triggers with wired USB connectivity. While lacking the advanced features of the DualShock 4, it provides reliable control for casual gaming, local multiplayer sessions, and younger players. Compatible with PS4, PC, and select Android devices via USB. Features dual vibration motors for immersive feedback. Brand new, sealed, third-party accessory.', 1, 1718400000, 1, 17000, '/assets/products/ps4-generic-x-controller.webp', 19500, 4.0, 0, 'Generic', 0, 0, 'gadgets');

-- PS4 Generic Controller Basic (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ps4-generic-controller-basic', 'PS4 Compatible Wired Controller - Basic - USB Connection, Standard Layout', 'gaming', 18000, 18000, 14000, 20, 0.20, '/assets/products/ps4-generic-controller-basic.webp', 'The most accessible entry point for PS4 controller needs. This generic wired controller offers standard PlayStation button layout, vibration feedback, and USB connectivity for reliable plug-and-play gaming. Ideal for local co-op sessions, children, or as an emergency backup when your primary controller needs charging. Compatible with PS4 and PC platforms. The lightweight design makes it comfortable for younger players. Brand new, sealed, third-party accessory.', 1, 1718400000, 1, 14000, '/assets/products/ps4-generic-controller-basic.webp', 16000, 3.9, 0, 'Generic', 0, 0, 'gadgets');

-- MEETION Gaming Headset Pro (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('meetion-gaming-headset-pro', 'MEETION Professional Gaming Headset - Brand New - 7.1 Surround Sound, 50mm Drivers, RGB LED', 'gaming', 105000, 105000, 88000, 12, 0.35, '/assets/products/meetion-gaming-headset-pro.webp', 'The MEETION Professional Gaming Headset delivers immersive audio performance for competitive and casual gamers alike. Featuring precision-tuned 50mm neodymium drivers, virtual 7.1 surround sound, and a noise-canceling flexible microphone, this headset ensures you hear every footstep and communicate with crystal clarity. The ergonomic over-ear design with breathable protein leather ear cushions and adjustable headband provides marathon comfort during extended gaming sessions. With universal 3.5mm connectivity, RGB lighting accents, and inline volume control, this headset is compatible with PS5, PS4, Xbox, Nintendo Switch, PC, and mobile devices. The braided cable resists tangling and wear. Brand new, sealed, premium third-party accessory.', 1, 1718400000, 1, 88000, '/assets/products/meetion-gaming-headset-pro.webp', 96000, 4.4, 0, 'MEETION', 0, 1, 'gadgets');

-- JBL PartyBox On-The-Go (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('jbl-partybox-on-the-go', 'JBL PartyBox On-The-Go Portable Party Speaker - Brand New - 100W, Wireless Mic, Light Show', 'audio', 580000, 580000, 520000, 4, 7.5, '/assets/products/jbl-partybox-on-the-go.webp', 'The JBL PartyBox On-The-Go brings the concert experience anywhere with 100W of powerful JBL Pro Sound. The built-in light show syncs to your music with dynamic RGB patterns, while the included wireless microphone transforms any gathering into a karaoke party. With IPX4 splashproof protection, 6-hour battery life, and a convenient shoulder strap, this portable party machine is perfect for beach trips, park gatherings, and impromptu celebrations. The mic and guitar inputs, plus Bluetooth and USB playback, ensure the party never stops. The 5.25-inch woofer and dual 1.5-inch tweeters produce surprisingly deep bass for its portable size. Brand new, sealed, original JBL packaging, 1-year JBL warranty.', 1, 1718400000, 1, 520000, '/assets/products/jbl-partybox-on-the-go.webp', 550000, 4.7, 1, 'JBL', 1, 1, 'gadgets');

-- PS5 Pro Carry Bag (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ps5-pro-carry-bag', 'PS5 Pro Protective Carry Bag - Brand New - Custom Foam Interior, Water-Resistant, Shoulder Strap', 'gaming', 72000, 72000, 58000, 8, 1.20, '/assets/products/ps5-pro-carry-bag.webp', 'Transport your PlayStation 5 Pro with confidence using this premium carry bag. Featuring a custom-molded interior with shock-absorbing foam padding, dedicated compartments for the console, controllers, cables, and games, this bag ensures your investment travels safely. The water-resistant exterior, reinforced handles, and adjustable shoulder strap provide comfort and protection whether you are heading to a friend house or a gaming tournament. Padded dividers prevent scratches and impacts during transit. The TSA-friendly design allows airport security screening without removing the console. Compatible with PS5 Pro, PS5 Disc, and Digital Editions. Brand new, sealed, premium third-party accessory.', 1, 1718400000, 1, 58000, '/assets/products/ps5-pro-carry-bag.webp', 65000, 4.5, 0, 'Generic', 0, 1, 'gadgets');

-- PS5 Dual Charging Dock (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ps5-dual-charging-dock-sony', 'Sony PS5 Dual Charging Dock - Brand New - Original, Charges 2 Controllers Simultaneously', 'gaming', 48000, 48000, 38000, 12, 0.25, '/assets/products/ps5-dual-charging-dock-sony.webp', 'Keep your battle station organized with the official Sony PS5 Dual Charging Dock. Designed to seamlessly match your PS5 aesthetic with the same white and black color scheme, this dock charges two DualSense wireless controllers simultaneously without connecting to the console. The click-in design ensures secure docking, while the intelligent charging indicators display charging status at a glance. Free up your console USB ports and ensure your controllers are always ready for your next gaming session. Compatible with both DualSense and DualSense Edge controllers. Brand new, sealed in original Sony packaging.', 1, 1718400000, 1, 38000, '/assets/products/ps5-dual-charging-dock-sony.webp', 43000, 4.7, 0, 'Sony', 0, 1, 'gadgets');

-- PS5 Cooling Stand with Charging (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ps5-cooling-stand-charging-dock', 'PS5 Cooling Stand with Dual Controller Charger - Brand New - Vertical Design, RGB LED', 'gaming', 48000, 48000, 38000, 10, 0.55, '/assets/products/ps5-cooling-stand-charging-dock.webp', 'Maximize your PS5 longevity and organization with this multifunctional cooling stand. Featuring high-velocity cooling fans that maintain optimal thermal performance during intensive gaming, dual controller charging docks, and dedicated storage slots for up to twelve game cases or discs, this stand transforms your setup into a command center. The vertical design saves shelf space while ensuring proper airflow, and the LED indicators add a premium aesthetic touch to your gaming environment. Compatible with both PS5 Disc and Digital Editions. Includes USB power cable. Brand new, sealed, premium third-party accessory tested for PS5 compatibility.', 1, 1718400000, 1, 38000, '/assets/products/ps5-cooling-stand-charging-dock.webp', 43000, 4.4, 0, 'Generic', 0, 0, 'gadgets');

-- PS5 Pro Disc Drive Add-On (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ps5-pro-disc-drive-addon', 'Sony PS5 Pro Disc Drive Add-On - Brand New - 4K UHD Blu-ray, Plug and Play, Official Sony', 'gaming', 235000, 235000, 210000, 6, 0.40, '/assets/products/ps5-pro-disc-drive-addon.webp', 'Expand your PS5 Digital Edition or PS5 Pro with the official Sony Disc Drive add-on. This modular 4K UHD Blu-ray drive attaches seamlessly to your console, enabling physical game disc playback, 4K movie watching, and backward compatibility with your existing PS4 and PS5 disc library. The plug-and-play installation requires no tools, and the drive matches your console aesthetic perfectly. For digital console owners who want the flexibility of physical media — including pre-owned game purchases and 4K Blu-ray movie collections — this is the essential upgrade. Brand new, sealed in original Sony packaging.', 1, 1718400000, 1, 210000, '/assets/products/ps5-pro-disc-drive-addon.webp', 220000, 4.7, 1, 'Sony', 1, 1, 'gadgets');

-- PS5 Pulse Elite Headset (ADD)
INSERT OR REPLACE INTO products (id, name, category, basePrice, price, wholesalePrice, stock, weightKg, image, description, active, createdAt, wholesale_available, wholesale_price, image_url, reseller_price, rating, featured, brand, is_bestseller, is_new, store_type)
VALUES ('ps5-pulse-elite-headset', 'Sony PS5 Pulse Elite Wireless Headset - Brand New - Planar Magnetic Drivers, AI Noise Rejection, 30H Battery', 'gaming', 295000, 295000, 255000, 6, 0.35, '/assets/products/ps5-pulse-elite-headset.webp', 'The Pulse Elite wireless headset represents the apex of PlayStation audio engineering. Featuring planar magnetic drivers that deliver audiophile-grade sound reproduction, AI-enhanced noise rejection for crystal-clear voice chat, and a retractable boom microphone, this headset brings studio quality to your gaming sessions. The wireless connection via the PlayStation Link USB adapter ensures lossless, ultra-low-latency audio with zero perceptible delay. With up to 30 hours of battery life, quick charging (10 minutes = 2 hours), and premium materials including plush leatherette ear cushions, this is the headset for discerning gamers who hear every detail — from enemy footsteps to orchestral scores. Compatible with PS5, PC, Mac, and PlayStation Portal. Brand new, sealed in original Sony packaging.', 1, 1718400000, 1, 255000, '/assets/products/ps5-pulse-elite-headset.webp', 275000, 4.8, 1, 'Sony', 1, 1, 'gadgets');
